for n,(x,y),scene in jobs:
    f=R/'references'/f'{n}-input.png';im.crop((x,y,x+1254,y+1254)).save(f);p.derived(f,[src],{'method':'native integer crop for specific seam repair','boxLTRB':[x,y,x+1254,y+1254]})
    prompt='Use case: precise native seam inpainting. Image1 is the EXACT target1254x1254 crop from an assembled Taoist Q game map. Image2 is the approved PRIMARY bright clean rounded handpainted style only. '+scene+' Same exact crop, camera, scale, object count, material colors, lighting and silhouette endpoints. Preserve outer80 pixels and all unaffected geometry. Do not add or remove objects, text, UI, lines or shadows. Keep native smooth brush detail without blur or sharpening. Output1254x1254.'
    call={'prompt':prompt,'referenced_image_paths':[f.as_posix(),h.STYLE],'transparent_background':False};h.savecall(n,call);meta.append({'name':n,'originXY':[x,y],'source':str(src),'input':str(f)})
